// Nimmt entgegen, was die Bruecke aus Teams weitergereicht hat, und macht daraus
// eine Anfrage an Rupert. Der Agent bleibt dabei unveraendert: er kennt Teams
// gar nicht, er sieht eine ganz normale Anfrage mit Quelle "teams".
const b = $input.first().json;
const kopf = b.headers || {};
const d = b.body || b;

if ((kopf['x-bridge-secret'] || '') !== '{{BRIDGE_SECRET}}') {
  return [{ json: { abbruch: true, grund: 'falsches oder fehlendes Bruecken-Geheimnis' } }];
}
if (!d.text || !d.conversationId || !d.serviceUrl) {
  return [{ json: { abbruch: true, grund: 'unvollstaendige Nutzlast' } }];
}

// Die Objekt-ID aus Entra ist genau der Schluessel, unter dem die persoenlichen
// Microsoft-Zugaenge liegen. Damit ist eine Person in Teams und in der
// Weboberflaeche dieselbe, ohne Zuordnungstabelle.
let userId = d.aadObjectId ? ('entra:' + d.aadObjectId) : ('teams:' + (d.fromId || 'unbekannt'));

// Wer sich in der Weboberflaeche verbunden hat, steht in user_identity_map mit
// seinem Web-Schluessel. Den benutzen wir auch aus Teams heraus, damit Profil,
// Gedaechtnis und Verlauf fuer beide Wege dieselben sind. Ohne Eintrag bleibt
// der Entra-Schluessel, dann kennt Rupert die Person nur ueber den Teams-Namen.
if (d.aadObjectId) {
  try {
    const rows = await this.helpers.httpRequest({
      method: 'GET',
      url: '{{SUPABASE_URL}}/rest/v1/user_identity_map?entra_key=eq.' + encodeURIComponent(userId) + '&select=legacy_key&order=linked_at.desc&limit=1',
      headers: { apikey: '{{SUPABASE_SERVICE_KEY}}', Authorization: 'Bearer {{SUPABASE_SERVICE_KEY}}' },
      json: true
    });
    if (Array.isArray(rows) && rows[0] && rows[0].legacy_key) userId = rows[0].legacy_key;
  } catch (e) { /* Nachschlagen ist optional, der Entra-Schluessel funktioniert immer */ }
}

// Auto-Zuordnung zu einem bestehenden Web-Profil (04.09.2026). Wer Microsoft
// ueber den Teams-Link verbunden hat, bekam bisher eine zweite Identitaet
// (web:mike und entra:...), mit getrenntem Gedaechtnis. Regel, absichtlich streng:
// nur Personen aus dem eigenen Mandanten, nur Web-Profile mit mindestens zwei
// Namenswoertern, und ALLE Woerter des Profilnamens muessen im Teams-Namen
// vorkommen. Genau ein Treffer, sonst bleibt es beim Entra-Profil.
const PG = { apikey: '{{SUPABASE_SERVICE_KEY}}', Authorization: 'Bearer {{SUPABASE_SERVICE_KEY}}' };
const normName = s => String(s || '').toLowerCase()
  .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
  .replace(/[,.;()]/g, ' ').split(/\s+/).filter(w => w.length > 1);
if (userId.startsWith('entra:') && d.fromName) {
  try {
    const tenantRows = await this.helpers.httpRequest({ method: 'GET',
      url: '{{SUPABASE_URL}}/rest/v1/template_credentials?template_id=eq.microsoft&cred_key=eq.tenant_id&select=cred_value',
      headers: PG, json: true });
    const eigenerMandant = Array.isArray(tenantRows) && tenantRows[0] && tenantRows[0].cred_value;
    if (eigenerMandant && d.tenantId && d.tenantId === eigenerMandant) {
      const teamsWoerter = new Set(normName(d.fromName));
      const profile = await this.helpers.httpRequest({ method: 'GET',
        url: '{{SUPABASE_URL}}/rest/v1/user_profiles?user_id=like.web:*&select=user_id,display_name',
        headers: PG, json: true });
      const treffer = (Array.isArray(profile) ? profile : []).filter(p => {
        const w = normName(p.display_name);
        return w.length >= 2 && w.every(x => teamsWoerter.has(x));
      });
      if (treffer.length === 1) {
        const legacy = treffer[0].user_id;
        const belegt = await this.helpers.httpRequest({ method: 'GET',
          url: '{{SUPABASE_URL}}/rest/v1/user_identity_map?legacy_key=eq.' + encodeURIComponent(legacy) + '&select=entra_key',
          headers: PG, json: true });
        if (!Array.isArray(belegt) || belegt.length === 0) {
          await this.helpers.httpRequest({ method: 'POST',
            url: '{{SUPABASE_URL}}/rest/v1/user_identity_map?on_conflict=legacy_key',
            headers: Object.assign({ 'Content-Type': 'application/json', Prefer: 'resolution=ignore-duplicates,return=minimal' }, PG),
            body: JSON.stringify({ legacy_key: legacy, entra_key: userId, entra_oid: d.aadObjectId }), json: false });
          userId = legacy;
        } else if (belegt[0].entra_key === userId) {
          userId = legacy;
        }
      }
    }
  } catch (e) { /* Zuordnung ist optional */ }
}

// Wer Rupert zuerst in Teams anspricht, hat noch kein Profil. Ohne Profil
// heisst die Person im Prompt "Unbekannter User", und Rupert kann sie nicht
// mit Namen ansprechen. Deshalb wird aus dem Teams-Anzeigenamen einmalig ein
// Profil angelegt. Nur anlegen, nie ueberschreiben: user_profiles.context ist
// das Freitextfeld, das der Agent selbst mit Gelerntem fuellt.
if (userId.startsWith('entra:') && d.fromName && String(d.fromName).trim()) {
  // "Schumacher, Florian" -> "Florian Schumacher"
  let name = String(d.fromName).trim().slice(0, 120);
  if (name.includes(',')) { const t = name.split(',').map(x => x.trim()).filter(Boolean); if (t.length === 2) name = t[1] + ' ' + t[0]; }
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: '{{SUPABASE_URL}}/rest/v1/user_profiles?on_conflict=user_id',
      headers: {
        apikey: '{{SUPABASE_SERVICE_KEY}}',
        Authorization: 'Bearer {{SUPABASE_SERVICE_KEY}}',
        'Content-Type': 'application/json',
        Prefer: 'resolution=ignore-duplicates,return=minimal'
      },
      body: JSON.stringify({ user_id: userId, name, display_name: name, context: 'Kontakt ueber Microsoft Teams.', setup_done: true }),
      json: false,
      timeout: 5000
    });
  } catch (e) { /* best effort, die Anfrage laeuft auch ohne Profil */ }
}

return [{ json: {
  abbruch: false,
  message: d.text,
  user_id: userId,
  session_id: 'teams:' + d.conversationId,
  display_name: d.fromName || '',
  serviceUrl: d.serviceUrl,
  conversationId: d.conversationId
} }];

// Schickt die Antwort ueber die Bruecke zurueck in die Teams-Konversation.
const vor = $('Vorbereiten').first().json;
const ant = $input.first().json;
const FALLBACK = 'Da bin ich haengen geblieben. Magst du die Frage anders oder in zwei Schritten stellen?';
let text = (ant && (ant.response || ant.output || ant.text)) || '';
// Der Agent liefert bei Abbruch einen englischen Systemtext, bei Fehlern kommt
// ueber "continueRegularOutput" ein Fehlerobjekt statt einer Antwort an.
if (!String(text).trim() || /max iterations|agent stopped/i.test(String(text)) || (ant && ant.error && !ant.response)) text = FALLBACK;

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: '{{BRIDGE_URL}}/reply',
    headers: { 'Content-Type': 'application/json', 'X-Bridge-Secret': '{{BRIDGE_SECRET}}' },
    body: JSON.stringify({ serviceUrl: vor.serviceUrl, conversationId: vor.conversationId, text: String(text) }),
    timeout: 20000
  });
  return [{ json: { gesendet: true, zeichen: String(text).length } }];
} catch (e) {
  return [{ json: { gesendet: false, fehler: String((e && e.message) || e) } }];
}

// Die Bruecke zeigt ab Eingang der Nachricht ein Tipp-Signal. Bricht der
// Adapter ab, kommt sonst nie ein /reply, und die Punkte laufen fuenf Minuten.
const vor = $input.first().json;
try {
  await this.helpers.httpRequest({ method: 'POST', url: '{{BRIDGE_URL}}/reply',
    headers: { 'Content-Type': 'application/json', 'X-Bridge-Secret': '{{BRIDGE_SECRET}}' },
    body: JSON.stringify({ conversationId: vor.conversationId || '', stop: true }), timeout: 5000 });
} catch (e) {}
return [{ json: { abbruch: true, grund: vor.grund } }];
